   456→#[test]
   457→fun test_support_asset_two_groups() {
   458→    use sui::test_scenario;
   459→    use math::float;
   460→
   461→    let mut scenario = test_scenario::begin(@0x1);
   462→    let ctx = scenario.ctx();
   463→
   464→    let mut registry = new_e_mode_registry(ctx);
   465→
   466→    // Create two emode groups
   467→    let group1 = registry.new_emode_group(0, scenario.ctx());
   468→    let group2 = registry.new_emode_group(0, scenario.ctx());
   469→
   470→    assert!(group1 == 0, 0);
   471→    assert!(group2 == 1, 1);
   472→
   473→    // Create params for TestCoinA in group1
   474→    let params_a_g1 = new_emode_params(
   475→        float::from_quotient(80, 100),  // collateral_factor: 0.8
   476→        float::from_quotient(85, 100),  // liquidation_factor: 0.85
   477→        float::from_quotient(5, 100),   // liquidation_incentive: 0.05
   478→        1000000000,                      // max_borrow_amount: 1B
   479→        float::from_quotient(110, 100), // borrow_weight: 1.1
   480→        float::from_quotient(1, 1000),  // flash_loan_fee_rate: 0.001
   481→        limiter::create_new_limiter_change(5000000000, 86400, 3600), // deposit_limiter: 5B per day, 1hr segments
   482→        limiter::create_new_limiter_change(2000000000, 86400, 3600), // borrow_limiter: 2B per day, 1hr segments
   483→    );
   484→
   485→    // Create params for TestCoinB in group2 with DIFFERENT values
   486→    let params_b_g2 = new_emode_params(
   487→        float::from_quotient(70, 100),  // collateral_factor: 0.7 (different)
   488→        float::from_quotient(75, 100),  // liquidation_factor: 0.75 (different)
   489→        float::from_quotient(10, 100),  // liquidation_incentive: 0.10 (different)
   490→        500000000,                       // max_borrow_amount: 500M (different)
   491→        float::from_quotient(120, 100), // borrow_weight: 1.2 (different)
   492→        float::from_quotient(2, 1000),  // flash_loan_fee_rate: 0.002 (different)
   493→        limiter::create_new_limiter_change(3000000000, 86400, 3600), // deposit_limiter: 3B per day (different)
   494→        limiter::create_new_limiter_change(1000000000, 86400, 3600), // borrow_limiter: 1B per day (different)
   495→    );
   496→
   497→    // Support assets in different groups
   498→    registry.support_asset<TestCoinA>(group1, params_a_g1, scenario.ctx());
